package main

// The museum. The captain asked for a guided walk through the laboratory where
// every piece is explained the way you would explain it leaning on a counter -
// no jargon, no assumed background, and every symbol translated into words the
// moment it appears.
//
// Two things live here: the DICCIONARIO, which decodes every symbol the visitor
// will meet, and the SALAS, eight rooms curated as a story rather than as a
// chronology. The last room is the honest one: the laboratory's own mistakes,
// with names and dates. That room is the point.

import (
	"encoding/json"
	"net/http"
	"path/filepath"
	"strings"
)

// Palabra is one entry of the glossary at the museum door.
type Palabra struct {
	Simbolo string `json:"simbolo"`
	Nombre  string `json:"nombre"`
	Criollo string `json:"criollo"`
}

// Pieza is one stop of the tour.
type Pieza struct {
	N        int        `json:"n"`
	Titulo   string     `json:"titulo"`
	Gancho   string     `json:"gancho"`
	Criollo  string     `json:"criollo"`
	Metafora string     `json:"metafora"`
	Mirar    string     `json:"mirar"`
	Simbolos [][]string `json:"simbolos"`
	Honesto  string     `json:"honesto"`
	Lamina   string     `json:"lamina"` // plate file name, or ""
	Exp      string     `json:"exp"`    // experiment dir to run live, or ""
	Hallazgo string     `json:"hallazgo"`
	Emoji    string     `json:"emoji"`
	Vel      string     `json:"vel"`
}

// SalaMuseo groups the stops of one room.
type SalaMuseo struct {
	Clave  string  `json:"clave"`
	Numero string  `json:"numero"`
	Titulo string  `json:"titulo"`
	Intro  string  `json:"intro"`
	Piezas []Pieza `json:"piezas"`
}

// diccionario decodes every symbol a visitor can bump into. Written for someone
// who has never seen a Greek letter in their life and should not feel small
// about it.
var diccionario = []Palabra{
	{"s", "el punto de la pregunta", "Es el lugar donde le preguntás algo a la máquina. Como el dial de una radio: lo movés y la máquina contesta otra cosa. Tiene dos perillas a la vez, por eso abajo aparecen σ y t."},
	{"σ", "sigma — la perilla horizontal", "De qué lado de la línea estás parado. Es la mitad «izquierda-derecha» del punto s. Toda la Hipótesis es una apuesta sobre esta perilla: dice que en los ceros vale siempre ½."},
	{"t", "la altura", "La mitad «arriba-abajo» del punto s. Es la altura a la que estás mirando, como los metros marcados en un poste."},
	{"ρ", "rho — una perla", "Un cero: un punto donde la máquina se calla del todo. En este taller los llamamos perlas, porque hay que pescarlas de a una."},
	{"γ", "gamma — la altura de una perla", "A qué altura quedó pescada esa perla. La primera está en γ = 14.134725. Es su número de identidad."},
	{"ζ", "zeta — la máquina", "La máquina que suma 1 + 1/2ˢ + 1/3ˢ + 1/4ˢ + … para el punto que le des. Euler descubrió que esa suma sobre TODOS los números es igual a una multiplicación sobre SOLO los primos. O sea: la máquina escucha a los primos."},
	{"ξ", "xi — la máquina peinada", "La misma máquina, pero vestida con unos factores extra que la vuelven perfectamente simétrica respecto de la línea del medio. Es la versión que se mira al espejo sin despeinarse."},
	{"Z(t)", "el detector de metales", "Un truco: sobre la línea del medio esta función da números normales (no de los raros), así que se puede ver dónde cambia de signo. Donde cambia de signo hay una perla enterrada. Es literalmente pasar el detector por la playa."},
	{"θ", "theta — el reloj", "El giro exacto que hay que aplicarle a la máquina para que el detector Z dé números normales. Es la perilla de sintonía."},
	{"λₙ", "lambda — los dientes del molde", "Una lista infinita de números — λ₁, λ₂, λ₃… — sacados de la máquina. Un teorema de Li dice: la Hipótesis es cierta si y solo si NINGUNO de estos números es negativo. λ₁ vale 0.0230957."},
	{"n", "el número de diente", "Cuál de los dientes de la lista estás mirando. El primero, el segundo, el cuarenta."},
	{"w", "el cambiaformas", "Una transformación que agarra el plano entero y lo mete adentro de un círculo. Lo de afuera pasa a ser lo de adentro. Se calcula w = 1 − 1/ρ."},
	{"p", "un primo cualquiera", "La letra que se usa para decir «acá va un número primo». Como decir «Fulano»."},
	{"ψ(x)", "psi — la escalera de los primos", "Una escalera que sube un escalón cada vez que aparece un primo (o una potencia de primo). El escalón no es de 1: es de ln p, el tamaño del primo medido en logaritmos."},
	{"π(x)", "pi de x — cuántos primos hay", "Cuántos primos hay hasta el número x. Ojo: NO es el π de 3.14159, es otra cosa que se escribe igual. Los matemáticos son así."},
	{"Σ", "sigma mayúscula — «sumá todo esto»", "Un cartelito que dice «sumá todos los términos que siguen». Nada más que eso."},
	{"Π", "pi mayúscula — «multiplicá todo esto»", "Lo mismo que Σ pero multiplicando en vez de sumar."},
	{"ln", "el logaritmo natural", "Le preguntás a un número «¿a qué potencia hay que elevar 2.718 para llegar a vos?». Sirve para aplastar números gigantes a un tamaño manejable: ln de un millón es apenas 13.8."},
	{"e", "el número 2.71828…", "Una constante que aparece sola en todo lo que crece o decrece de manera natural: intereses, poblaciones, enfriamiento del mate."},
	{"i", "la unidad imaginaria", "Un número inventado que cumple i × i = −1. Suena a trampa y no lo es: sirve para que los puntos vivan en un plano en vez de en una recta. Es lo que le da la segunda perilla a s."},
	{"|x|", "el tamaño, la distancia", "Las dos barritas quieren decir «el tamaño de esto, sin importar el signo». Una distancia nunca puede ser negativa — eso lo dijo el capitán y resultó ser la clave de una fórmula entera."},
	{"Re / Im", "parte real / parte imaginaria", "Las dos mitades de un punto del plano: Re es cuánto se corrió a los costados, Im cuánto subió o bajó."},
	{"Γ", "gamma mayúscula — el factorial estirado", "El factorial (5! = 5×4×3×2×1) pero estirado para que funcione con cualquier número, no solo con los enteros. Es una de las piezas del vestido de ξ."},
	{"Λ(n)", "lambda mayúscula — el peso de un número", "Vale ln p si el número es una potencia de un primo p, y vale cero si no. Es la manera de decir «este número aporta a la escalera, este otro no»."},
	{"O(x)", "«no crece más rápido que»", "Una manera de acotar. Decir que un error es O(√x) es decir «como mucho crece como la raíz cuadrada», sin comprometerse con el número exacto."},
	{"⟺", "«si y solo si»", "Las dos cosas van juntas o no va ninguna. Si pasa una pasa la otra, y al revés también."},
	{"1e-16", "un decimal seguido de quince ceros", "La manera corta de escribir números diminutos. 1e-16 es 0.0000000000000001 — el límite de precisión de una computadora común. Cuando una medición da eso, es exacta hasta donde la máquina puede ver."},
}

func (p *puente) apiMuseo(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	_ = json.NewEncoder(w).Encode(map[string]any{
		"diccionario": diccionario,
		"guiado":      recorridoGuiado,
		"completo":    salasCompletas,
	})
}

// apiLaminaMuseo serves a plate by file name rather than by experiment, since a
// museum stop may hang a plate produced by a different experiment than the one
// it invites you to run.
func (p *puente) apiLaminaMuseo(w http.ResponseWriter, r *http.Request) {
	f := r.URL.Query().Get("f")
	if f == "" || strings.ContainsAny(f, `/\`) || strings.Contains(f, "..") {
		http.NotFound(w, r)
		return
	}
	p.mu.Lock()
	ruta := p.rutaLamina(f)
	p.mu.Unlock()
	if ruta == "" {
		http.NotFound(w, r)
		return
	}
	switch strings.ToLower(filepath.Ext(ruta)) {
	case ".svg":
		w.Header().Set("Content-Type", "image/svg+xml; charset=utf-8")
	case ".png":
		w.Header().Set("Content-Type", "image/png")
	default:
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	}
	http.ServeFile(w, r, ruta)
}

